import math

def cardinal_temp(T, t_min=2.925, t_opt=22.505, t_max=42.085):
    if T <= t_min or T >= t_max: return 0.0
    p = (t_max - t_opt) / (t_opt - t_min)
    return ((T - t_min) / (t_opt - t_min)) * (((t_max - T) / (t_max - t_opt)) ** p)

def step_growth(X, T, co2_ppm, par_umol, dt_s, cc=31.9):
    g_car = 0.001959 * cardinal_temp(T)
    g = 1.0 / (1.0/0.007 + 1.0/0.005 + 1.0/max(g_car, 1e-12)) if g_car > 0 else 0.0
    C = min(co2_ppm, 1200.0) * 1.8295e-6
    Gamma = 5.2e-5 * (2.0 ** ((T - 20.0) / 10.0))
    eps_I = 1.7e-8 * par_umol * 0.2188
    g_C = max(0.0, g * (C - Gamma))
    P = (1.0 - math.exp(-cc * X)) * (eps_I * g_C / (eps_I + g_C)) if (eps_I + g_C) > 0 else 0.0
    R = 2.65e-7 * X * (2.0 ** ((T - 25.0) / 10.0))
    return X + (0.544 * P - R) * dt_s

# A2 currently: units=1015.83 on 452.1 m2 -> 2.247 kg/m2 FW -> X = 2.247 * 0.093 = 0.2090 kg/m2
# Target X = 2.494 * 0.093 = 0.2319 kg/m2
X0 = 0.2090
target = 0.2319

for pct in [100, 70, 55, 45]:
    for co2 in [850, 500]:
        for T_light in [21.5, 17.5]:
            X = X0
            for d in range(6):
                for h in range(24):
                    # 9h day light (6..14), 8h dark (15..22), 7h night light (23..5)
                    if 6 <= h <= 14:
                        par = 266.0 * (pct / 100.0)
                        X = step_growth(X, T_light, co2, par, 3600)
                    elif 23 <= h or h <= 5:
                        # night stays at 21.5, co2=850, par=266 if we don't change night schedule for A
                        X = step_growth(X, 21.5, 850, 266.0, 3600)
                    else:
                        X = step_growth(X, 17.0, 420, 0.0, 3600)
                if X >= target:
                    print(f'Day only change (pct={pct}, co2={co2}, T={T_light}): ready at end of day +{d+1} (Day {3+d+1}), X={X:.4f}')
                    break
            else:
                print(f'Day only change (pct={pct}, co2={co2}, T={T_light}): after 6d X={X:.4f}')
"
